import{_ as a,c as i,o as t,a2 as r}from"./chunks/framework.bjzS3PU6.js";const u=JSON.parse('{"title":"Kai Shepherd","description":"","frontmatter":{},"headers":[],"relativePath":"entries/people/Kai-Shepherd.md","filePath":"entries/people/Kai-Shepherd.md"}'),n={name:"entries/people/Kai-Shepherd.md"};function o(s,e,l,h,d,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="kai-shepherd" tabindex="-1">Kai Shepherd <a class="header-anchor" href="#kai-shepherd" aria-label="Permalink to &quot;Kai Shepherd&quot;">​</a></h1><hr><p><strong>BORN</strong>: c. 1981<br><strong>RESIDENCE</strong>: Saint Juniper, California<br><strong>STATUS</strong>: Missing (October 1995)</p><hr><p><strong>Kai Shepherd</strong> is a Saint Juniper resident who disappeared under unexplained circumstances at Hill Devil State Park in October 1995. The incident, witnessed by multiple individuals, became a catalyst for activist investigation into alleged <a href="./../organizations/Miter-Corporation">Miter Corporation</a> operations in the area.</p><p><strong>At a glance</strong></p><ul><li>Disappeared at Hill Devil State Park (October 1995)</li><li>Part of a group of four young hikers at the time of the incident</li><li>Witnesses reported seeing an unidentified aerial craft near the security perimeter of SJ SECURELAB facility</li><li>Disappearance occurred near restricted Miter Corporation property</li><li>The incident prompted formation of <a href="./../organizations/The-Bloc">The Bloc</a> activist organization</li><li>Case remains unresolved with no official investigation findings made public</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Kai Shepherd was one of four young people hiking at Hill Devil State Park on a weekend in October 1995. The group, accompanied by a dog named Pubes, encountered a security fence marked with &quot;DO NOT ENTER&quot; signage for SJ SECURELAB—a property later identified as belonging to the <a href="./../organizations/Miter-Corporation">Miter Corporation</a>. According to eyewitness accounts, the group heard a buzzing sound and observed an unidentified triangular craft. Witnesses reported that Shepherd was separated from the group and subsequently disappeared.</p><p>The incident devastated the local community and affected multiple families in <a href="./../locations/Saint-Juniper">Saint Juniper</a>. No official law enforcement findings were made public, and the case remains unresolved.</p><h2 id="the-incident" tabindex="-1">The incident <a class="header-anchor" href="#the-incident" aria-label="Permalink to &quot;The incident&quot;">​</a></h2><h3 id="october-1995" tabindex="-1">October 1995 <a class="header-anchor" href="#october-1995" aria-label="Permalink to &quot;October 1995&quot;">​</a></h3><p>On an October weekend in 1995, Shepherd joined three friends for a casual hike on a maintained trail at Hill Devil State Park, a recreational area near Saint Juniper. The group brought a pet pug named Pubes. Witnesses recalled that Shepherd was wearing a distinctive red hoodie, green shorts, and purple high-top sneakers. As evening approached, they found themselves near a security fence marked with &quot;DO NOT ENTER&quot; signage identifying the property as belonging to SJ SECURELAB.</p><p>According to testimony from the three other hikers, the group heard a strange buzzing sound at this location. Looking up, they observed an unidentified aerial craft described as triangular in shape. The craft emitted a bright light directed at the group. Witnesses stated that Shepherd was &quot;pulled up effortlessly&quot; into the craft.</p><h3 id="aftermath" tabindex="-1">Aftermath <a class="header-anchor" href="#aftermath" aria-label="Permalink to &quot;Aftermath&quot;">​</a></h3><p>The disappearance prompted local concern and affected Shepherd&#39;s family, the witnesses, and the broader Saint Juniper community. One witness, later known by the alias <a href="./Z-L1NE">Z*L1NE</a>, became obsessed with understanding the incident and spent extensive time researching at the <a href="./../locations/St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a>.</p><h2 id="impact-and-investigations" tabindex="-1">Impact and investigations <a class="header-anchor" href="#impact-and-investigations" aria-label="Permalink to &quot;Impact and investigations&quot;">​</a></h2><h3 id="formation-of-the-bloc" tabindex="-1">Formation of The Bloc <a class="header-anchor" href="#formation-of-the-bloc" aria-label="Permalink to &quot;Formation of The Bloc&quot;">​</a></h3><p>The incident became a catalyst for independent investigation into activities at Hill Devil State Park. <a href="./Z-L1NE">Z*L1NE</a>, one of the witnesses to Shepherd&#39;s disappearance, met computer security researchers <a href="./1NK">1NK</a> and <a href="./GUMM1">GUMM1</a> while researching the incident. Their subsequent discoveries of alleged Miter Corporation operations in the area led to the formation of <a href="./../organizations/The-Bloc">The Bloc</a> in 1999.</p><p>According to The Bloc&#39;s materials, their investigation revealed that the Miter Corporation operated a research facility in the woods at Hill Devil State Park. The organization has claimed that the facility conducts unauthorized human experimentation programs.</p><h3 id="public-documentation" tabindex="-1">Public documentation <a class="header-anchor" href="#public-documentation" aria-label="Permalink to &quot;Public documentation&quot;">​</a></h3><p>Documentation of the incident exists in investigative materials compiled by researchers and activists. The case has been cited by The Bloc as evidence of unexplained disappearances in proximity to Miter Corporation facilities.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./Z-L1NE">Z*L1NE</a></li><li><a href="./../organizations/The-Bloc">The Bloc</a></li><li><a href="./../locations/Hill-Devil-State-Park">Hill Devil State Park</a></li><li><a href="./../locations/Saint-Juniper">Saint Juniper</a></li><li><a href="./../organizations/Miter-Corporation">Miter Corporation</a></li><li><a href="./../locations/St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a></li><li><a href="./1NK">1NK</a></li><li><a href="./GUMM1">GUMM1</a></li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Eyewitness testimony from October 1995 incident — Documented by researchers and activists investigating Hill Devil State Park disappearances</li><li><a href="./../../lore/GBOY-MANIFESTO">G*BOY Manifesto</a> — References the formative incident that led to The Bloc&#39;s investigation (1999)</li><li>Regional documentation of unexplained disappearances near Saint Juniper (mid-1990s)</li></ol><hr><p><em>This article is part of the Saint Juniper Research Documentation Project</em></p>',28)])])}const f=a(n,[["render",o]]);export{u as __pageData,f as default};
